import { describe, expect, it } from "vitest";
import { rewriteDeprecatedToolCalls } from "./deprecatedToolNames.js";
import * as contract from "./mcpContract.js";
function toolCall(name, args) {
    return JSON.stringify({
        jsonrpc: "2.0",
        id: 1,
        method: "tools/call",
        params: { name, arguments: args ?? {} },
    });
}
function parsedCall(body) {
    return JSON.parse(body);
}
const RENAMES = [
    ["read_traces", "get_traces"],
    ["read_trace_labels", "get_trace_verdicts"],
    ["read_grader_labels", "get_grader_verdicts"],
    ["read_span_field", "get_span_field"],
    ["get_experiment_traces", "list_experiment_traces"],
    ["update_template", "save_template"],
    ["update_agent_labels", "save_agent_verdicts"],
    ["set_human_labels", "save_human_verdicts"],
    ["add_grader_to_experiment_group", "add_graders_to_experiment_group"],
    ["create_dataset", "save_dataset"],
];
describe("rewriteDeprecatedToolCalls", () => {
    it.each(RENAMES)("maps %s onto %s", (deprecated, current) => {
        const result = rewriteDeprecatedToolCalls(toolCall(deprecated));
        expect(parsedCall(result.body).params.name).toBe(current);
        expect(result.deprecatedNames).toEqual([deprecated]);
    });
    it.each(RENAMES)("%s resolves to a registered tool (%s)", (_deprecated, current) => {
        expect(contract.TOOL_NAMES).toContain(current);
    });
    it("passes current names through untouched", () => {
        const body = toolCall("get_traces", { traceIds: ["a"] });
        const result = rewriteDeprecatedToolCalls(body);
        expect(result.body).toBe(body);
        expect(result.deprecatedNames).toEqual([]);
    });
    it("widens the deprecated singular graderId into a graderIds array", () => {
        const result = rewriteDeprecatedToolCalls(toolCall("add_grader_to_experiment_group", {
            experimentGroupId: "group-1",
            graderId: "grader-1",
        }));
        expect(parsedCall(result.body).params.arguments).toEqual({
            experimentGroupId: "group-1",
            graderIds: ["grader-1"],
        });
    });
    it("leaves an already-plural graderIds alone", () => {
        const result = rewriteDeprecatedToolCalls(toolCall("add_grader_to_experiment_group", {
            experimentGroupId: "group-1",
            graderIds: ["grader-1", "grader-2"],
        }));
        expect(parsedCall(result.body).params.arguments).toEqual({
            experimentGroupId: "group-1",
            graderIds: ["grader-1", "grader-2"],
        });
    });
    it.each([
        "search_traces",
        "save_agent_verdicts",
        "save_agent_labels",
        "rerun_graders_on_experiment",
        "add_graders_to_experiment",
        "remove_graders_from_experiment",
        "list_experiment_traces",
        "get_replay_status",
        "save_experiment",
        "get_experiment",
    ])("maps the deprecated testRunId argument of %s onto experimentId", (name) => {
        const result = rewriteDeprecatedToolCalls(toolCall(name, { testRunId: "run-1", limit: 5 }));
        expect(parsedCall(result.body).params).toEqual({
            name,
            arguments: { experimentId: "run-1", limit: 5 },
        });
        expect(result.deprecatedNames).toEqual([`${name}.testRunId`]);
    });
    it("maps the deprecated testRunIds of save_experiment_group onto experimentIds", () => {
        const result = rewriteDeprecatedToolCalls(toolCall("save_experiment_group", { testRunIds: ["run-1", "run-2"] }));
        expect(parsedCall(result.body).params.arguments).toEqual({
            experimentIds: ["run-1", "run-2"],
        });
        expect(result.deprecatedNames).toEqual(["save_experiment_group.testRunIds"]);
    });
    it("keeps experimentId when a caller sends both names", () => {
        const result = rewriteDeprecatedToolCalls(toolCall("get_experiment", {
            experimentId: "run-new",
            testRunId: "run-old",
        }));
        expect(parsedCall(result.body).params.arguments).toEqual({
            experimentId: "run-new",
        });
        expect(result.deprecatedNames).toEqual([]);
    });
    it("drops testRunIds without recording it when a caller sends both names", () => {
        const result = rewriteDeprecatedToolCalls(toolCall("save_experiment_group", {
            experimentIds: ["run-1"],
            testRunIds: ["run-1"],
            name: "group",
        }));
        expect(parsedCall(result.body).params.arguments).toEqual({
            experimentIds: ["run-1"],
            name: "group",
        });
        expect(result.deprecatedNames).toEqual([]);
    });
    it("renames both the tool and its argument for a deprecated tool name", () => {
        const result = rewriteDeprecatedToolCalls(toolCall("get_experiment_traces", { testRunId: "run-1" }));
        expect(parsedCall(result.body).params).toEqual({
            name: "list_experiment_traces",
            arguments: { experimentId: "run-1" },
        });
        expect(result.deprecatedNames).toEqual([
            "get_experiment_traces",
            "list_experiment_traces.testRunId",
        ]);
    });
    it("passes a current experimentId call through byte for byte", () => {
        const body = toolCall("get_experiment", { experimentId: "run-1" });
        expect(rewriteDeprecatedToolCalls(body)).toEqual({
            body,
            deprecatedNames: [],
        });
    });
    it.each(Object.entries({
        search_traces: contract.searchTraces,
        save_agent_verdicts: contract.saveAgentVerdicts,
        save_agent_labels: contract.saveAgentLabels,
        save_experiment_group: contract.saveExperimentGroup,
        get_experiment: contract.getExperiment,
        get_replay_status: contract.getReplayStatus,
    }))("%s advertises the experiment ID, not testRunId", (_name, tool) => {
        expect(Object.keys(tool.inputSchema)).not.toContain("testRunId");
        expect(Object.keys(tool.inputSchema)).not.toContain("testRunIds");
    });
    it("rewrites only the deprecated entries of a batch", () => {
        const body = JSON.stringify([
            {
                jsonrpc: "2.0",
                id: 1,
                method: "tools/call",
                params: { name: "read_traces", arguments: {} },
            },
            {
                jsonrpc: "2.0",
                id: 2,
                method: "tools/call",
                params: { name: "list_datasets", arguments: {} },
            },
        ]);
        const result = rewriteDeprecatedToolCalls(body);
        const parsed = JSON.parse(result.body);
        expect(parsed.map((message) => message.params.name)).toEqual([
            "get_traces",
            "list_datasets",
        ]);
        expect(result.deprecatedNames).toEqual(["read_traces"]);
    });
    it("does not touch methods other than tools/call", () => {
        const body = JSON.stringify({
            jsonrpc: "2.0",
            id: 1,
            method: "tools/list",
            params: { name: "read_traces" },
        });
        expect(rewriteDeprecatedToolCalls(body).body).toBe(body);
    });
    it("returns malformed bodies verbatim", () => {
        expect(rewriteDeprecatedToolCalls("not json").body).toBe("not json");
        expect(rewriteDeprecatedToolCalls("not json").deprecatedNames).toEqual([]);
    });
    it("keeps deprecated names out of the advertised surface", () => {
        for (const [deprecated] of RENAMES) {
            expect(contract.TOOL_NAMES).not.toContain(deprecated);
        }
    });
});
const PUBLISHED_TOOL_NAMES = [
    "add_grader_to_experiment_group",
    "add_graders_to_dataset",
    "add_graders_to_experiment",
    "add_traces_to_dataset",
    "create_dataset",
    "get_api_key_context",
    "get_bitfab_api_key",
    "get_database_connection_status",
    "get_experiment",
    "get_experiment_group",
    "get_experiment_traces",
    "generate_trace_assertions",
    "get_replay_status",
    "get_template",
    "get_template_reference",
    "list_datasets",
    "list_experiment_groups",
    "list_experiments",
    "list_graders",
    "list_organizations",
    "list_trace_functions",
    "read_grader_labels",
    "read_span_field",
    "read_trace_labels",
    "read_traces",
    "remove_graders_from_dataset",
    "remove_graders_from_experiment",
    "remove_traces_from_dataset",
    "save_experiment_group",
    "save_experiment",
    "save_grader",
    "save_grader_labels",
    "save_agent_labels",
    "save_human_labels",
    "get_trace_labels",
    "get_grader_labels",
    "generate_label_evidence",
    "search_traces",
    "set_human_labels",
    "update_agent_labels",
    "update_template",
];
describe("published tool surface stays answerable", () => {
    it.each(PUBLISHED_TOOL_NAMES)("%s resolves to a registered tool", (name) => {
        if (contract.TOOL_NAMES.includes(name)) {
            return;
        }
        const result = rewriteDeprecatedToolCalls(toolCall(name));
        expect(result.deprecatedNames, `${name} was removed from the surface with no shim mapping`).toEqual([name]);
        expect(contract.TOOL_NAMES).toContain(parsedCall(result.body).params.name);
    });
});
describe("trace-plan retirement", () => {
    it.each([
        "create_trace_plan",
        "update_trace_plan",
        "save_trace_plan",
        "get_trace_plan",
        "confirm_trace_plan",
        "list_trace_plans",
        "cancel_trace_plan",
    ])("does not resolve %s", (name) => {
        const result = rewriteDeprecatedToolCalls(toolCall(name));
        expect(result.deprecatedNames).toEqual([]);
        expect(contract.TOOL_NAMES).not.toContain(parsedCall(result.body).params.name);
    });
});
describe("label tools renamed to verdict tools", () => {
    it.each([
        ["save_agent_labels", "save_agent_verdicts"],
        ["save_human_labels", "save_human_verdicts"],
        ["save_grader_labels", "save_grader_verdicts"],
        ["get_trace_labels", "get_trace_verdicts"],
        ["get_grader_labels", "get_grader_verdicts"],
        ["generate_label_evidence", "generate_verdict_evidence"],
    ])("keeps %s registered beside %s rather than rewriting it", (old, current) => {
        expect(contract.TOOL_NAMES).toContain(old);
        expect(contract.TOOL_NAMES).toContain(current);
        const body = toolCall(old);
        expect(rewriteDeprecatedToolCalls(body)).toEqual({
            body,
            deprecatedNames: [],
        });
    });
});
